  "excludes.advisoryImmichDb": "O Immich guarda os álbuns, os rostos e as datas de cada fotografia numa base de dados PostgreSQL que corre noutro container, não neste, por isso este backup não a contém. Restaurar a partir daqui devolve as fotografias, mas sem os álbuns, os rostos e as datas. O BombVault faz dump desse container de base de dados sozinho quando lhe faz backup, por isso confirma que está no teu agendamento.",
