  // Restore from another BombVault repo — Recovery page (#61 task 11)
  "recovery.abTitle": "Importar do plugin Appdata.Backup",
  "recovery.abIntro": "Transforma os arquivos que o plugin Appdata.Backup escreveu em pontos de restauro dos contentores correspondentes, cada um com a data em que o plugin o criou. Os arquivos só são lidos, nunca alterados nem apagados. Cada um é descompactado junto ao repositório, copiado, e a cópia descompactada é removida outra vez, por isso esse local precisa de espaço para o maior arquivo.",
