  "recovery.foreignKeyHint": "A chave de 64 caracteres do kit de recuperação da outra instância. A tua própria chave fica intacta.",
  "recovery.foreignCredsIntro": "Isto parece um repositório remoto, por isso são necessárias as credenciais do backend do outro servidor. Só são usadas nesta sessão e nunca são guardadas. As tuas próprias credenciais externas não são reutilizadas aqui de propósito: seriam enviadas para um endereço que acabaste de escrever.",
