  "anomaly.settings.title": "Anomalias",
  "anomaly.settings.hint": "Compara cada backup de uma entrada com o seu próprio histórico e indica o que não encaixa. Corre em segundo plano depois de cada backup e não atrasa nenhum. A maioria das verificações começa após 10 backups de uma entrada; as falhas, a reescrita da maior parte dos dados e uma origem quase vazia são verificadas desde o início. O espaço livre é vigiado nos repositórios locais e nos repositórios rclone que o indicam; na partilha de utilizador do Unraid é o espaço livre de todo o array.",
  "anomaly.settings.toggle": "Detetar anomalias",
  "anomaly.settings.sensitivity": "Sensibilidade",
  "anomaly.settings.sensitivityHint": "Rigorosa assinala alterações mais pequenas, Permissiva só as grandes, Equilibrada serve para a maioria dos servidores. Cada entrada pode ter a sua própria definição em Anomalias, Monitorização.",
  "anomaly.settings.notifyMin": "Enviar uma notificação para",
  "anomaly.settings.notifyHint": "Usa os canais configurados em Notificações. Cada entrada pode alterá-lo em Anomalias, Monitorização. As falhas repetidas de backups e dumps e as verificações de restauro agendadas falhadas já enviam a sua própria mensagem, por isso não são enviadas uma segunda vez.",
  "anomaly.settings.notifyMuted": "Neste momento nada é enviado: as notificações estão desligadas ou não há nenhum canal configurado.",
  "anomaly.settings.openNotifications": "Abrir as definições de notificações",
  "anomaly.settings.holdToggle": "Manter os backups antigos quando uma origem encolhe muito ou é reescrita",
  "anomaly.settings.holdHint": "Três achados suspendem a eliminação de backups antigos: uma origem que de repente está quase vazia, uma que ficou muito mais pequena e um backup que voltou a guardar a maior parte dos dados, que é o aspeto de um ransomware. De outra forma a retenção apagaria os bons backups antigos um a um. Enquanto uma anomalia destas estiver aberta, mantêm-se os backups antigos só dessa entrada (ou desse dump de base de dados ou conjunto de dados ZFS); tudo o resto é limpo como de costume. Confirma a anomalia ou marca-a como esperada para retomar.",
